#!/bin/bash
sòm() {
  local a=$1
  local b=$2
  echo $((a + b))
}

si_par() {
  [ $(( $1 % 2 )) -eq 0 ] && return 0 || return 1
}

rezilta=$(sòm 40 2)
echo "40 + 2 = $rezilta"
if si_par 10; then echo "10 se par"; fi

#!/bin/bash
set -euo pipefail
VERBOSE=0
SOTI=""

montre_èd() { echo "Itilizasyon: $0 [-v] [-o fichye] dosye"; }

while getopts ":hvo:" opt; do
  case $opt in
    h) montre_èd; exit 0;;
    v) VERBOSE=1;;
    o) SOTI="$OPTARG";;
    \?) echo "Opsyon enkoni: -$OPTARG" >&2; exit 2;;
    :) echo "-$OPTARG bezwen yon valè" >&2; exit 2;;
  esac
done
shift $((OPTIND - 1))
[ $# -eq 0 ] && { montre_èd; exit 2; }
